-- Klipvi shared caption template library (workspace_id null), generated from selection_v2/captions.py TEMPLATES
-- (settings = DEFAULTS + the template's overrides). Re-runnable: updates existing rows by name.
on conflict (name) where workspace_id is null do update set label = excluded.label, settings = excluded.settings, sort = excluded.sort;

update public.workspaces set default_template_id = (select id from public.caption_templates where workspace_id is null and name = 'clean')
where default_template_id is null;
